(async()=>{
 const check=(name,condition,detail='')=>parent.reportTest(name,!!condition,detail);
 const tick=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 const settle=async()=>{map.stop();await tick();await new Promise(resolve=>setTimeout(resolve,320));};
 const near=(a,b)=>Math.abs(a-b)<1;
 const box=id=>document.getElementById(id).getBoundingClientRect();
 try{
  await settle();
  check('47 партнёров имеют категории и описания',brands.length===47&&brands.every(b=>PARTNER_INFO[b[0]]?.length===3));
  check('1200 партнёрских точек',points.length===1200);
  check('Кэшбэк 10–40%, шаг 5%',points.every(p=>p.cash>=10&&p.cash<=40&&p.cash%5===0));
  check('Кэшбэк един для всех точек партнёра',points.every(p=>p.cash===partnerCashbacks.get(p.name)));
  check('Шапка 88 px',near(document.querySelector('.screen-header').getBoundingClientRect().height,88));
  check('Единственный переключатель в шапке',document.querySelectorAll('.screen-header input').length===1);
  check('Активная карта 570 px',near(box('map').top,88)&&near(box('map').height,570));
  check('Основная шторка начинается на 658 px',near(box('offersSheet').top,658));
  check('Категории недоступны для нажатия',[...document.querySelectorAll('.category-chip')].every(el=>el.disabled));
  refreshOfferList();
  const rows=[...document.querySelectorAll('.offer-row')];
  check('Предложения отсортированы по весу',rows.length>1&&rows.every((r,i)=>!i||Number(rows[i-1].dataset.weight)>=Number(r.dataset.weight)));
  check('Список соответствует точкам активной карты',rows.map(r=>Number(r.dataset.pinId)).join()===visiblePartnerOffers().map(p=>p.pinId).join());
  const savedCount=rows.length;
  toggleSheet('list');await settle();
  check('Список поднимается к Header',near(box('offersSheet').top,88));
  check('Развёрнутый список сохраняет предложения',document.querySelectorAll('.offer-row').length===savedCount&&sheetElements.empty.hidden);
  toggleSheet('list');await settle();
  check('Список сворачивается в активное состояние',near(box('offersSheet').top,658)&&near(box('map').height,570));
  const chosen=visiblePartnerOffers()[0];const cashBefore=chosen.cash;
  selectPoint(chosen);await settle();
  check('Открывается шторка выбранного пина',!sheetElements.detail.hidden&&document.getElementById('detailName').textContent===chosen.name);
  check('Выбранная карта 228 px',near(box('map').top,88)&&near(box('map').height,228)&&near(box('detailSheet').top,316));
  check('Основная шторка свернута и не перехватывает ввод',near(box('offersSheet').top,658)&&sheetElements.offers.inert);
  check('Партнёрский кэшбэк в карточке',document.getElementById('detailCash').textContent==='Кэшбэк '+cashBefore+'%');
  check('Категория и описание выбранного партнёра',document.getElementById('detailCategory').textContent===PARTNER_INFO[chosen.name][0]&&document.getElementById('detailAbout').textContent===PARTNER_INFO[chosen.name][1]);
  check('Логотип выбранного партнёра',document.getElementById('detailLogo').getAttribute('src')===chosen.logo);
  check('Выбранный пин единственный',document.querySelectorAll('.marker.selected').length===1);
  const toggle=document.getElementById('newLogicToggle');toggle.checked=true;toggle.onchange();await settle();
  check('Переключение логики сохраняет выбранное предложение',sheetState.selected===chosen&&!sheetElements.detail.hidden&&near(box('map').height,228));
  toggle.checked=false;toggle.onchange();await settle();
  const logo=document.querySelector('.marker.selected .logo').getBoundingClientRect();
  check('Активный пин центрирован визуально',near(logo.x+logo.width/2,box('map').width/2)&&near(logo.y+logo.height/2,88+228/2));
  toggleSheet('detail');await settle();
  check('Подъём карточки ограничен высотой содержимого',near(box('detailSheet').top,expandedSheetTop('detail'))&&box('detailSheet').top>=88);
  document.getElementById('closeDetail').click();await settle();
  check('Закрытие карточки восстанавливает карту',sheetElements.detail.hidden&&!sheetElements.offers.inert&&near(box('map').height,570));
  const oldCamera={center:map.getCenter().toArray(),zoom:map.getZoom()};
  map.jumpTo({center:[0,0],zoom:16});render();await tick();refreshOfferList();
  check('Пустая область показывает zero state',!sheetElements.empty.hidden&&sheetElements.list.hidden&&document.querySelectorAll('.offer-row').length===0);
  toggleSheet('list');await settle();
  check('Короткая пустая шторка поднимается только на высоту контента',box('offersSheet').top>88&&near(box('offersSheet').top,expandedSheetTop('list')));
  toggleSheet('list');map.jumpTo(oldCamera);render();await settle();
  document.getElementById('newLogicToggle').checked=true;render();await tick();refreshOfferList();
  const newRows=[...document.querySelectorAll('.offer-row')];
  check('Сортировка сохранена в новой логике',newRows.length>1&&newRows.every((r,i)=>!i||Number(newRows[i-1].dataset.weight)>=Number(r.dataset.weight)));
  selectPoint(visiblePartnerOffers()[0]);await settle();
  check('Новая логика открывает один выбранный пин',!sheetElements.detail.hidden&&document.querySelectorAll('.marker.selected').length===1&&near(box('map').height,228));
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await settle();
  check('Escape закрывает выбранное предложение',sheetElements.detail.hidden);
  const currentCash=new Map(points.map(p=>[p.name,p.cash]));
  map.zoomTo(map.getZoom()+1,{duration:0});render();await tick();
  check('Проценты сохраняются при перемещении, масштабировании и выборе',points.every(p=>currentCash.get(p.name)===p.cash));
  const images=[...document.querySelectorAll('img[src^="assets/"]')];
  await Promise.all(images.map(img=>img.decode().catch(()=>{})));
  check('Все статические изображения загружены',images.every(img=>img.complete&&img.naturalWidth>0));
  check('Нет горизонтального переполнения',document.documentElement.scrollWidth===375);
  parent.reportTest('Проверки завершены',true);
 }catch(error){parent.reportTest('Исключение в тестах',false,error.stack);}
})();
